import{_ as e,c as t,o as s,a2 as a}from"./chunks/framework.DdOM6S6U.js";const q=JSON.parse('{"title":"ChatController","description":"","frontmatter":{"sidebarPos":5,"sidebarTitle":"ChatController"},"headers":[],"relativePath":"system-reference/backend/http/controllers/chat-controller.md","filePath":"system-reference/backend/http/controllers/chat-controller.md","lastUpdated":1778363927000}'),o={name:"system-reference/backend/http/controllers/chat-controller.md"},r=a('<h1 id="chatcontroller" tabindex="-1">ChatController <a class="header-anchor" href="#chatcontroller" aria-label="Permalink to &quot;ChatController&quot;">​</a></h1><p><strong>File</strong>: <code>src/Http/Controllers/ChatController.php</code><br><strong>Namespace</strong>: <code>Unusualify\\Modularous\\Http\\Controllers</code><br><strong>Extends</strong>: <code>App\\Http\\Controllers\\Controller</code></p><p>Handles chat messages, attachments, and pinned messages for a <code>Chat</code> model instance. Supports both paginated fetching and time-based queries for real-time catch-up.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="index-request-request-chat-chat-jsonresponse" tabindex="-1"><code>index(Request $request, Chat $chat): JsonResponse</code> <a class="header-anchor" href="#index-request-request-chat-chat-jsonresponse" aria-label="Permalink to &quot;`index(Request $request, Chat $chat): JsonResponse`&quot;">​</a></h3><p>Returns messages for a chat room.</p><ul><li>When <code>from</code> is present in the request, returns all messages newer than that timestamp (real-time catch-up). User&#39;s own messages are excluded from this query.</li><li>When <code>from</code> is absent, returns a paginated list of all messages ordered newest-first.</li></ul><p><strong>Request parameters</strong>:</p><table><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>from</code></td><td><code>datetime</code></td><td>Only return messages newer than this timestamp</td></tr></tbody></table><h3 id="store-request-request-chat-chat-jsonresponse" tabindex="-1"><code>store(Request $request, Chat $chat): JsonResponse</code> <a class="header-anchor" href="#store-request-request-chat-chat-jsonresponse" aria-label="Permalink to &quot;`store(Request $request, Chat $chat): JsonResponse`&quot;">​</a></h3><p>Creates a new chat message. Accepts an optional <code>attachments</code> field (Filepond temporary file keys). The parent <code>Chat</code> model is touched (updated_at refreshed) after the message is stored.</p><h3 id="attachments-request-request-chat-chat-jsonresponse" tabindex="-1"><code>attachments(Request $request, Chat $chat): JsonResponse</code> <a class="header-anchor" href="#attachments-request-request-chat-chat-jsonresponse" aria-label="Permalink to &quot;`attachments(Request $request, Chat $chat): JsonResponse`&quot;">​</a></h3><p>Returns all file attachments for a chat room, ordered by upload date.</p><h3 id="update-request-request-id-jsonresponse" tabindex="-1"><code>update(Request $request, $id): JsonResponse</code> <a class="header-anchor" href="#update-request-request-id-jsonresponse" aria-label="Permalink to &quot;`update(Request $request, $id): JsonResponse`&quot;">​</a></h3><p>Updates the body of an existing message. Touches the parent <code>Chat</code> model&#39;s timestamp.</p><h3 id="pinnedmessage-request-request-id-jsonresponse" tabindex="-1"><code>pinnedMessage(Request $request, $id): JsonResponse</code> <a class="header-anchor" href="#pinnedmessage-request-request-id-jsonresponse" aria-label="Permalink to &quot;`pinnedMessage(Request $request, $id): JsonResponse`&quot;">​</a></h3><p>Returns the currently pinned message for the chat identified by <code>$id</code>.</p><h3 id="destroy-request-request-chatmessage-message-jsonresponse" tabindex="-1"><code>destroy(Request $request, ChatMessage $message): JsonResponse</code> <a class="header-anchor" href="#destroy-request-request-chatmessage-message-jsonresponse" aria-label="Permalink to &quot;`destroy(Request $request, ChatMessage $message): JsonResponse`&quot;">​</a></h3><p>Deletes a chat message. Intended for message owners or admins.</p><h2 id="filepond-attachments" tabindex="-1">Filepond Attachments <a class="header-anchor" href="#filepond-attachments" aria-label="Permalink to &quot;Filepond Attachments&quot;">​</a></h2><p>Attachments are uploaded via Filepond before the message is created. The <code>store</code> action resolves each Filepond temporary key to a permanent <code>File</code> record and associates it with the message.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./filepond-controller">FilepondController</a> — handles temporary Filepond uploads</li><li><a href="./file-library-controller">FileLibraryController</a> — permanent file management</li></ul>',23),n=[r];function d(h,c,l,i,p,u){return s(),t("div",null,n)}const f=e(o,[["render",d]]);export{q as __pageData,f as default};
